CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE companies(id text PRIMARY KEY,name text NOT NULL,city text NOT NULL,lat double precision NOT NULL,lng double precision NOT NULL,verified boolean NOT NULL DEFAULT false,settings jsonb NOT NULL DEFAULT '{"minDays":2,"buffer":1,"prep":19000,"open":"09:00","close":"17:00"}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE CHECK(email=lower(email)),name text NOT NULL,password_hash text NOT NULL,role text NOT NULL DEFAULT 'traveler' CHECK(role IN ('traveler','owner','admin')),company_id text REFERENCES companies,profile jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),CHECK((role='owner')=(company_id IS NOT NULL)));
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,csrf text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiration ON sessions(expires_at);
CREATE TABLE vehicles(id text PRIMARY KEY,company_id text NOT NULL REFERENCES companies,name text NOT NULL,type text NOT NULL,asset text NOT NULL,city text NOT NULL,lat double precision NOT NULL,lng double precision NOT NULL,seats integer NOT NULL CHECK(seats>=0),sleeps integer NOT NULL CHECK(sleeps>0),daily integer NOT NULL CHECK(daily>0),prep integer NOT NULL DEFAULT 0 CHECK(prep>=0),deposit integer NOT NULL CHECK(deposit>=0),min_days integer NOT NULL DEFAULT 2 CHECK(min_days>0),auto boolean NOT NULL DEFAULT false,pets boolean NOT NULL DEFAULT false,instant boolean NOT NULL DEFAULT true,km integer,features jsonb NOT NULL DEFAULT '[]',description text NOT NULL DEFAULT '',tagline text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','hidden')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX vehicles_company ON vehicles(company_id);
CREATE TABLE stock_items(company_id text NOT NULL REFERENCES companies,id text NOT NULL,name text NOT NULL,quantity integer NOT NULL CHECK(quantity>=0),price integer NOT NULL CHECK(price>=0),unit text NOT NULL CHECK(unit IN ('day','trip')),excluded_types jsonb NOT NULL DEFAULT '[]',PRIMARY KEY(company_id,id));
CREATE TABLE seasons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id text NOT NULL REFERENCES companies,vehicle_id text REFERENCES vehicles,start_date date NOT NULL,end_date date NOT NULL,rate integer NOT NULL CHECK(rate>0),name text NOT NULL,CHECK(end_date>start_date));
CREATE TABLE quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,vehicle_id text NOT NULL REFERENCES vehicles,input jsonb NOT NULL,snapshot jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reference text NOT NULL UNIQUE DEFAULT ('VL-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),user_id uuid NOT NULL REFERENCES users,company_id text NOT NULL REFERENCES companies,vehicle_id text NOT NULL REFERENCES vehicles,quote_id uuid UNIQUE REFERENCES quotes,start_date date NOT NULL,end_date date NOT NULL,guests integer NOT NULL CHECK(guests>0),status text NOT NULL CHECK(status IN ('held','pending','confirmed','in_rental','completed','cancelled','rejected','expired')),hold_until timestamptz,payment_status text NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','partial','paid','refund_pending','refunded')),deposit_status text NOT NULL DEFAULT 'scheduled' CHECK(deposit_status IN ('scheduled','authorized','released','claim_pending')),total_minor integer NOT NULL CHECK(total_minor>=0),paid_minor integer NOT NULL DEFAULT 0 CHECK(paid_minor>=0),deposit_minor integer NOT NULL CHECK(deposit_minor>=0),buffer integer NOT NULL DEFAULT 1 CHECK(buffer>=0),snapshot jsonb NOT NULL,traveler jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(end_date>start_date));
CREATE INDEX bookings_customer ON bookings(user_id,created_at);
CREATE INDEX bookings_owner ON bookings(company_id,start_date);
CREATE TABLE allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vehicle_id text NOT NULL REFERENCES vehicles,booking_id uuid UNIQUE REFERENCES bookings ON DELETE CASCADE,company_id text NOT NULL REFERENCES companies,occupied daterange NOT NULL,active boolean NOT NULL DEFAULT true,reason text NOT NULL DEFAULT 'booking',created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT vehicle_no_overlap EXCLUDE USING gist(vehicle_id WITH =,occupied WITH &&) WHERE(active));
CREATE TABLE booking_extras(booking_id uuid NOT NULL REFERENCES bookings ON DELETE CASCADE,company_id text NOT NULL,item_id text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),price integer NOT NULL CHECK(price>=0),unit text NOT NULL CHECK(unit IN ('day','trip')),FOREIGN KEY(company_id,item_id) REFERENCES stock_items(company_id,id),PRIMARY KEY(booking_id,item_id));
CREATE TABLE idempotency(user_id uuid NOT NULL REFERENCES users,operation text NOT NULL,key text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,operation,key));
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES bookings,kind text NOT NULL CHECK(kind IN ('payment','refund')),amount_minor integer NOT NULL CHECK(amount_minor>0),provider text NOT NULL DEFAULT 'local_test',status text NOT NULL DEFAULT 'succeeded',idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES bookings,kind text NOT NULL CHECK(kind IN ('insurance','vignette')),status text NOT NULL DEFAULT 'unavailable',details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE amendments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES bookings,requested_by uuid NOT NULL REFERENCES users,input jsonb NOT NULL,snapshot jsonb NOT NULL,previous jsonb,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_pending_amendment ON amendments(booking_id) WHERE status='pending';
CREATE TABLE handovers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES bookings,created_by uuid NOT NULL REFERENCES users,kind text NOT NULL CHECK(kind IN ('pickup','return')),mileage integer NOT NULL CHECK(mileage>=0),fuel text NOT NULL,notes text NOT NULL DEFAULT '',checks jsonb NOT NULL,confirmed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(booking_id,kind));
CREATE TABLE favorites(user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,vehicle_id text NOT NULL REFERENCES vehicles ON DELETE CASCADE,PRIMARY KEY(user_id,vehicle_id));
CREATE TABLE comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vehicle_id text NOT NULL REFERENCES vehicles,author_id uuid NOT NULL REFERENCES users,booking_id uuid REFERENCES bookings,type text NOT NULL CHECK(type IN ('question','review')),text text NOT NULL,rating integer CHECK(rating BETWEEN 1 AND 5),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','published','hidden','rejected')),reply text,reply_by uuid REFERENCES users,reason text,created_at timestamptz NOT NULL DEFAULT now(),CHECK((type='review' AND booking_id IS NOT NULL AND rating IS NOT NULL) OR (type='question' AND booking_id IS NULL AND rating IS NULL)),UNIQUE(booking_id,author_id));
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vehicle_id text NOT NULL REFERENCES vehicles,traveler_id uuid NOT NULL REFERENCES users,author_id uuid NOT NULL REFERENCES users,text text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX messages_conversation ON messages(vehicle_id,traveler_id,created_at);
CREATE TABLE tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id text NOT NULL REFERENCES companies,booking_id uuid REFERENCES bookings,title text NOT NULL,done boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,booking_id uuid REFERENCES bookings,comment_id uuid REFERENCES comments,subject text NOT NULL,description text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved')),resolution text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE articles(id text PRIMARY KEY,title text NOT NULL,kind text NOT NULL CHECK(kind IN ('guide','inspiration')),summary text NOT NULL,body jsonb NOT NULL,asset text NOT NULL,published boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE camps(id text PRIMARY KEY,name text NOT NULL,region text NOT NULL,lat double precision NOT NULL,lng double precision NOT NULL,features jsonb NOT NULL,description text NOT NULL,is_example boolean NOT NULL DEFAULT true);
CREATE TABLE audit(id bigserial PRIMARY KEY,user_id uuid REFERENCES users,company_id text REFERENCES companies,action text NOT NULL,resource text,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id bigserial PRIMARY KEY,kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done','failed')),attempts integer NOT NULL DEFAULT 0,next_run timestamptz NOT NULL DEFAULT now(),error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE local_mail(id bigserial PRIMARY KEY,user_id uuid REFERENCES users,subject text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reset_tokens(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,expires_at timestamptz NOT NULL,used_at timestamptz);
